-- Check compliance case coverage
SELECT COUNT(*) as total_txn FROM transactionrecord;
SELECT COUNT(DISTINCT cc.transref) as txn_with_compliance FROM compliancecase cc;

SELECT trdref, COUNT(*), ARRAY_AGG(DISTINCT modfreq), ARRAY_AGG(DISTINCT cancelpct) 
FROM transactionrecord 
GROUP BY trdref HAVING COUNT(*) > 1;

SELECT COUNT(*) FROM trader t
JOIN transactionrecord tr ON tr.trdref = t.tradereg
JOIN compliancecase cc ON cc.transref = tr.transreg;

